messages.content:
Berikut manifest game **Vertebrata Run** — Endless Runner edukasi klasifikasi mamalia, reptil, dan ikan dengan tema Clean Modern.

```js
AISYS.defineGame({
  schema: 1, kit: "endless-runner",
  id: "vertebrata-run", title: "Vertebrata Run", seed: "vertebrata-01",
  theme: { preset: "clean-modern" },

  learning: {
    subject: "Ilmu Pengetahuan Alam (Biologi)",
    concept: "Klasifikasi hewan vertebrata: mamalia, reptil, dan ikan",
    objectives: ["Mengelompokkan hewan berdasarkan ciri kelompoknya"],
    misconceptions: ["Paus dan lumba-lumba dianggap ikan karena hidup di air"],
    mode: "category",
    categories: [
      { id: "mamalia", label: "Mamalia", color: "#2F80ED" },
      { id: "reptil",  label: "Reptil",  color: "#3FA34D" },
      { id: "ikan",    label: "Ikan",    color: "#00A3C4" }
    ],
    items: [
      { id: "kucing",     label: "Kucing",     category: "mamalia", explain: "Berbulu dan menyusui anaknya, ciri khas mamalia." },
      { id: "lumba-lumba", label: "Lumba-lumba", category: "mamalia", explain: "Mamalia laut: bernapas dengan paru-paru dan menyusui." },
      { id: "kelelawar",  label: "Kelelawar",  category: "mamalia", explain: "Mamalia bersayap yang menyusui anaknya." },
      { id: "komodo",     label: "Komodo",     category: "reptil",  explain: "Reptil terbesar, bersisik dan bertelur." },
      { id: "penyu",      label: "Penyu",      category: "reptil",  explain: "Reptil bercangkang yang bertelur di pasir." },
      { id: "buaya",      label: "Buaya",      category: "reptil",  explain: "Reptil bersisik dan pemangsa di perairan." },
      { id: "hiu",        label: "Hiu",        category: "ikan",    explain: "Ikan yang bernapas dengan insang, bukan mamalia." },
      { id: "koi",        label: "Koi",        category: "ikan",    explain: "Ikan air tawar yang bernapas dengan insang." },
      { id: "tuna",       label: "Tuna",       category: "ikan",    explain: "Ikan laut yang bernapas dengan insang." }
    ],
    target: { rotateAfterCorrect: 5, bias: 0.5 }
  },

  player: { x: 220, w: 44, h: 56, gravity: 2400, jumpVelocity: 900, lives: 3, invulnerableSec: 1.2 },
  world:  { groundY: 600, speed: 360, maxSpeed: 720, accel: 6 },

  spawner: {
    interval: [0.9, 1.5],
    table: [
      { type: "hazard", id: "batu",     w: 44, h: 48, weight: 3 },
      { type: "hazard", id: "semak",    w: 90, h: 24, weight: 2 },
      { type: "item", weight: 5, heights: ["ground", "mid", "high"] }
    ]
  },

  rules: {
    perSecond: 5,
    correct: { score: 50, sfx: "coin" },
    wrong:   { score: -20, sfx: "hit", showExplain: true },
    hazard:  { lives: -1, sfx: "hit", shake: 8 },
    combo:   { step: 5, max: 4 },
    difficulty: { everySec: 15, speed: 25 }
  }
});
// END_OF_MANIFEST
```

Game ini menguji pemain mengambil hewan sesuai kategori target, dengan lumba-lumba sebagai item jebakan kunci miskonsepsi "mamalia laut = ikan". Asumsi: rintangan batu dan semak dipakai sebagai penghalang netral karena PRD tidak menyebut rintangan spesifik.
